// Existing 2-layer system prompt architecture
// Layer 1: TOOL_CONSTITUTION (hidden from UI, always included as system role)
// Layer 2: AgentMode prompt (user-selectable, visible in UI)

export const TOOL_CONSTITUTION = `...tool usage rules...`;

export const AGENT_MODES = {
  code_assistant: `...code-focused persona...`,
  file_explorer: `...file navigation persona...`,
  terminal_expert: `...command execution persona...`,
  full_stack_developer: `...comprehensive development persona...`
};

// Current composeSystemPrompt function merges layers
